const DEMO_USER = { email: 'admin@saudeevida.com', password: 'saudevida123' };
const LOCAL_KEY = 'saude-e-vida-local-state-v2';
let serverAvailable = false;
let state = null;
let currentPage = 'overview';
let searchTerm = '';

const fallbackState = {
  company: { id: 1, name: 'Saúde e Vida', segment: 'Produtos naturais e bem-estar' },
  user: { id: 1, name: 'Admin', email: DEMO_USER.email, role: 'Administrador' },
  shifts: [],
  products: [{ id: 1, name: 'Chá verde com limão', code: 'SV-001', category: 'Chás e infusões', unit: 'UN', stock: 34, min: 12, price: 24.9, cost: 11.5, infinite: false }, { id: 2, name: 'Granola artesanal 500g', code: 'SV-002', category: 'Alimentos naturais', unit: 'UN', stock: 8, min: 10, price: 29.9, cost: 14.2, infinite: false }, { id: 3, name: 'Pasta de amendoim integral', code: 'SV-003', category: 'Alimentos naturais', unit: 'UN', stock: 21, min: 8, price: 21.5, cost: 9.8, infinite: false }],
  clients: [{ id: 1, name: 'Mariana Alves', phone: '(85) 99921-3211', email: 'mariana@email.com' }, { id: 2, name: 'Rafael Nogueira', phone: '(85) 98840-1180', email: 'rafael@email.com' }],
  suppliers: [{ id: 1, name: 'Verde Campo Distribuidora', contact: 'contato@verdecampo.com', phone: '(85) 3221-0042' }],
  sales: [], movements: [], orders: [], cashEntries: [], expenses: [], receivables: [], budgets: [], appointments: []
};

const navSections = [
  { title: 'Central de gestão', items: [['overview', '⌁', 'Visão geral']] },
  { title: 'Operacional', items: [['stock', '◇', 'Estoque'], ['stock-variants', '◇', 'Estoque de roupas'], ['production', '⚙', 'Produção'], ['product-reports', '▥', 'Relatórios de produtos'], ['orders', '🛒', 'Pedidos'], ['suppliers', '♧', 'Fornecedores'], ['appointments', '◫', 'Agendamentos']] },
  { title: 'Comercial', items: [['clients', '♙', 'Clientes'], ['budgets', '◈', 'Orçamentos'], ['cash', '▣', 'Caixa']] },
  { title: 'Financeiro', items: [['employee-costs', '▤', 'Custos por funcionários'], ['entries', '↗', 'Entradas'], ['receivables', '◷', 'Contas a receber'], ['expenses', '↙', 'Saídas'], ['financial-reports', '▥', 'Relatórios financeiros']] },
  { title: 'Relacionamento', items: [['crm', '♡', 'CRM / RFM']] },
  { title: 'Administração', items: [['users', '♙', 'Usuários'], ['access', '♢', 'Gestão de acessos'], ['company', '▥', 'Minha empresa'], ['fiscal', '▱', 'Configuração fiscal']] }
];
const pageNames = Object.fromEntries(navSections.flatMap(section => section.items.map(item => [item[0], item[2]])));

const money = value => Number(value || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const number = value => Number(value || 0).toLocaleString('pt-BR');
const today = () => new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Fortaleza' }).format(new Date());
const escapeHtml = value => String(value ?? '').replace(/[&<>'"]/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[char]));
const total = (items, key = 'amount') => (items || []).reduce((sum, item) => sum + Number(item[key] || 0), 0);
const currentShift = () => state?.shifts?.find(shift => shift.status === 'aberto');
const statusText = status => ({ pendente: 'Pendente', aprovado: 'Aprovado', em_processamento: 'Em processamento', recebido: 'Recebido', cancelado: 'Cancelado', ABERTA: 'Aberta', PAGA: 'Paga', CANCELADA: 'Cancelada', finalizada: 'Finalizada', pago: 'Pago', parcial: 'Parcial', quitado: 'Quitado', nao_pago: 'Não pago' }[status] || status || '—');
const tag = status => { const text = statusText(status); const cls = /pendente|aberta|não pago|análise|baixo/i.test(text) ? 'warning' : /cancel|sem estoque/i.test(text) ? 'danger' : /recebido|pago|finalizada|saudável|ativo|quitado/i.test(text) ? '' : 'blue'; return `<span class="tag ${cls}">${escapeHtml(text)}</span>`; };

function showToast(message) { const toast = document.getElementById('toast'); toast.textContent = message; toast.classList.add('show'); clearTimeout(window.toastTimer); window.toastTimer = setTimeout(() => toast.classList.remove('show'), 3300); }
function show(id) { document.getElementById(id).classList.remove('hidden'); }
function hide(id) { document.getElementById(id).classList.add('hidden'); }
function saveLocal() { localStorage.setItem(LOCAL_KEY, JSON.stringify(state)); }
async function request(path, options = {}) { const response = await fetch(path, { ...options, headers: { 'Content-Type': 'application/json', ...(options.headers || {}) } }); const payload = response.status === 204 ? null : await response.json(); if (!response.ok) throw new Error(payload?.error || 'Não foi possível concluir a operação'); return payload; }
async function loadState() { if (window.location.protocol !== 'file:') { try { const response = await fetch('/api/state', { cache: 'no-store' }); if (response.ok) { serverAvailable = true; const payload = await response.json(); return payload.data; } } catch { serverAvailable = false; } } try { const saved = localStorage.getItem(LOCAL_KEY); return saved ? { ...fallbackState, ...JSON.parse(saved) } : structuredClone(fallbackState); } catch { return structuredClone(fallbackState); } }
async function reloadState() { if (serverAvailable) state = (await request('/api/state')).data; else state = await loadState(); saveLocal(); renderPage(); }

function renderSidebar() { document.getElementById('sidebar').innerHTML = `<div class="sidebar-brand"><a class="brand brand-light" href="#" data-action="go-dashboard"><span class="brand-mark"><span>✦</span></span><span><strong>Saúde</strong> e Vida</span></a></div>${navSections.map(section => `<div class="nav-section">${section.title}<span>⌄</span></div><ul class="nav-list">${section.items.map(([id, icon, label]) => `<li><button class="nav-item ${currentPage === id ? 'active' : ''}" data-page="${id}"><span class="nav-icon">${icon}</span>${label}</button></li>`).join('')}</ul>`).join('')}<div class="sidebar-bottom"><p>Ambiente personalizado<br /><strong>Loja Saúde e Vida</strong></p></div>`; }
function pageHeading(eyebrow, title, description, action = '') { return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${action ? `<div class="heading-actions">${action}</div>` : ''}</div>`; }
function actionButton(label, action, icon = '+', secondary = false) { return `<button class="button ${secondary ? 'button-secondary' : 'button-primary'} button-small" data-action="${action}"><span>${icon}</span>${label}</button>`; }
function productRows(products = state.products) { return products.map(product => `<tr><td><strong>${escapeHtml(product.name)}</strong><br /><small class="muted">${escapeHtml(product.code || '')} · ${escapeHtml(product.category || 'Sem categoria')}</small></td><td>${number(product.stock)} ${escapeHtml(product.unit || 'UN')}</td><td>${product.infinite ? '—' : `${number(product.min)} ${escapeHtml(product.unit || 'UN')}`}</td><td>${money(product.price)}</td><td>${product.infinite ? tag('Estoque infinito') : product.stock <= product.min ? tag('Estoque baixo') : tag('Saudável')}</td><td><button class="text-link" data-action="stock-entry" data-id="${product.id}">Entrada</button></td></tr>`).join(''); }
function financialEntries() { return state.cashEntries || []; }
function financialExpenses() { return state.expenses || []; }
function dashboard() { const entries = financialEntries(); const expenses = financialExpenses(); return { totalEntradas: total(entries), totalSaidas: total(expenses), saldo: total(entries) - total(expenses), clientesComCompras: new Set((state.sales || []).filter(sale => sale.clientId).map(sale => sale.clientId)).size, estoqueBaixo: state.products.filter(product => !product.infinite && product.stock > 0 && product.stock <= product.min).length, semEstoque: state.products.filter(product => !product.infinite && product.stock <= 0).length, aReceber: (state.receivables || []).filter(item => item.status === 'ABERTA').reduce((sum, item) => sum + Number(item.amount || 0) - Number(item.paidAmount || 0), 0), estoqueValor: state.products.reduce((sum, product) => sum + Number(product.stock || 0) * Number(product.cost || 0), 0) }; }

function renderOverview() { const k = dashboard(); const low = state.products.filter(product => !product.infinite && product.stock <= product.min); return pageHeading('Central de gestão', 'Central de Gestão', 'Visão completa e objetiva da operação da Saúde e Vida.', actionButton('Nova venda', 'new-sale', '＋')) + `<div class="kpi-grid"><div class="kpi-card"><div class="kpi-top"><span class="kpi-label">Clientes com compras</span><span class="kpi-icon">♙</span></div><div class="kpi-value">${number(k.clientesComCompras)}</div><div class="kpi-foot">Clientes identificados no período</div></div><div class="kpi-card"><div class="kpi-top"><span class="kpi-label">Estoque baixo</span><span class="kpi-icon">!</span></div><div class="kpi-value">${number(k.estoqueBaixo)} SKUs</div><div class="kpi-foot">Posição atual do estoque</div></div><div class="kpi-card"><div class="kpi-top"><span class="kpi-label">Sem estoque</span><span class="kpi-icon">×</span></div><div class="kpi-value">${number(k.semEstoque)} SKUs</div><div class="kpi-foot">Saldo zero ou negativo</div></div><div class="kpi-card"><div class="kpi-top"><span class="kpi-label">Saldo financeiro</span><span class="kpi-icon">↗</span></div><div class="kpi-value">${money(k.saldo)}</div><div class="kpi-foot">Entradas menos saídas registradas</div></div></div><div class="dashboard-grid"><div class="panel"><div class="panel-header"><div><h3 class="panel-title">Resumo financeiro</h3><div class="panel-subtitle">Consolidação dos lançamentos registrados</div></div><button class="text-link" data-page="financial-reports">Ver relatório →</button></div><div class="metric-grid"><div class="metric-box"><p>Entradas</p><strong>${money(k.totalEntradas)}</strong></div><div class="metric-box"><p>Saídas</p><strong>${money(k.totalSaidas)}</strong></div><div class="metric-box"><p>A receber</p><strong>${money(k.aReceber)}</strong></div></div><div class="chart">${[42, 58, 44, 72, 61, 88, 67].map((height, index) => `<div class="chart-bar-wrap"><div class="chart-bar ${index === 6 ? 'current' : ''}" style="height:${height}%"></div><span class="chart-label">${['02', '03', '04', '05', '06', '07', '08'][index]}</span></div>`).join('')}</div></div><div class="panel"><div class="panel-header"><div><h3 class="panel-title">Atividade recente</h3><div class="panel-subtitle">Últimas vendas e movimentos</div></div><button class="text-link" data-page="cash">Ver caixa →</button></div><div class="activity">${(state.sales || []).slice(0, 4).map(sale => `<div class="activity-row"><span class="activity-symbol">↗</span><div><strong>Venda #${sale.id}</strong><small>${escapeHtml(sale.client || 'Consumidor final')} · ${money(sale.total)}</small></div><span class="status-dot"></span></div>`).join('') || '<div class="empty-state">Nenhuma atividade registrada.</div>'}</div></div></div><div class="panel low-stock"><div class="panel-header"><div><h3 class="panel-title">Estoque atual</h3><div class="panel-subtitle">Necessidade é a quantidade para atingir o mínimo, não uma sugestão de compra.</div></div><button class="text-link" data-page="stock">Ver estoque →</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Produto</th><th>Disponível</th><th>Mínimo</th><th>Preço</th><th>Status</th><th></th></tr></thead><tbody>${productRows(low.length ? low : state.products.slice(0, 4))}</tbody></table></div></div>`; }
function renderStock() { const products = state.products.filter(product => `${product.name} ${product.code} ${product.category}`.toLowerCase().includes(searchTerm.toLowerCase())); return pageHeading('Operacional', 'Estoque', 'Posição atual, mínimos e histórico de movimentações.', `${actionButton('Novo produto', 'new-product', '＋', true)}${actionButton('Nova entrada', 'new-entry', '＋')}`) + `<div class="panel"><div class="filter-bar"><div class="search-box"><span>⌕</span><input id="tableSearch" placeholder="Buscar produto, SKU ou categoria" value="${escapeHtml(searchTerm)}" /></div><button class="button button-secondary button-small" data-page="product-reports">Relatório do estoque</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Produto / SKU</th><th>Disponível</th><th>Mínimo</th><th>Preço venda</th><th>Status</th><th></th></tr></thead><tbody>${productRows(products) || '<tr><td colspan="6"><div class="empty-state">Nenhum produto encontrado.</div></td></tr>'}</tbody></table></div></div><div class="panel low-stock"><div class="panel-header"><div><h3 class="panel-title">Últimos movimentos</h3><div class="panel-subtitle">Origem e motivo de cada alteração no saldo.</div></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Data</th><th>Produto</th><th>Tipo</th><th>Quantidade</th><th>Origem</th></tr></thead><tbody>${(state.movements || []).slice(0, 10).map(movement => `<tr><td>${movement.date}</td><td><strong>${escapeHtml(movement.product)}</strong></td><td>${tag(movement.type)}</td><td>${number(movement.quantity)}</td><td>${escapeHtml(movement.reason)}</td></tr>`).join('') || '<tr><td colspan="5"><div class="empty-state">Nenhum movimento.</div></td></tr>'}</tbody></table></div></div>`; }
function renderCash() { const shift = currentShift(); const shiftPanel = shift ? `<div class="notice"><strong>Turno aberto:</strong> ${escapeHtml(shift.employee)} · abertura ${money(shift.openingAmount)} · iniciado em ${new Date(shift.openedAt).toLocaleString('pt-BR')} <button class="text-link" data-action="close-shift">Fechar turno</button></div>` : `<div class="notice"><strong>Caixa fechado:</strong> abra um turno antes de registrar uma venda ou saída em dinheiro. <button class="text-link" data-action="open-shift">Abrir caixa</button></div>`; return pageHeading('Comercial', 'Caixa', 'Registre vendas, pagamentos, descontos e movimentos do turno.', actionButton('Nova venda', 'new-sale', '＋')) + shiftPanel + `<div class="metric-grid"><div class="metric-box"><p>Vendas registradas</p><strong>${number((state.sales || []).length)}</strong></div><div class="metric-box"><p>Total vendido</p><strong>${money(total(state.sales || [], 'total'))}</strong></div><div class="metric-box"><p>Ticket médio</p><strong>${money(total(state.sales || [], 'total') / Math.max((state.sales || []).length, 1))}</strong></div></div><div class="panel"><div class="panel-header"><div><h3 class="panel-title">Histórico do caixa</h3><div class="panel-subtitle">Vendas finalizadas e seus pagamentos.</div></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Venda</th><th>Cliente</th><th>Itens</th><th>Pagamento</th><th>Total</th><th>Data</th></tr></thead><tbody>${(state.sales || []).map(sale => `<tr><td><strong>#${sale.id}</strong></td><td>${escapeHtml(sale.client || 'Consumidor final')}</td><td>${sale.items.map(item => `${escapeHtml(item.name)} × ${item.quantity}`).join('<br />')}</td><td>${sale.payments.map(payment => tag(payment.method === 'CARTAO' ? `Cartão ${payment.cardType || ''}` : payment.method)).join(' ')}</td><td>${money(sale.total)}</td><td>${sale.date}</td></tr>`).join('') || '<tr><td colspan="6"><div class="empty-state">Nenhuma venda registrada.</div></td></tr>'}</tbody></table></div></div>`; }
function renderOrders() { return pageHeading('Operacional', 'Pedidos', 'Compre produtos, acompanhe o recebimento e controle pagamentos do fornecedor.', actionButton('Novo pedido', 'new-order', '＋')) + `<div class="notice"><strong>Fluxo operacional:</strong> ao marcar um pedido como recebido, cada item entra no estoque e recebe um movimento de origem pedido. Pagamentos ficam separados do recebimento físico.</div><div class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Pedido</th><th>Fornecedor</th><th>Itens</th><th>Total</th><th>Status físico</th><th>Status financeiro</th><th></th></tr></thead><tbody>${(state.orders || []).map(order => `<tr><td><strong>${escapeHtml(order.number)}</strong><br /><small class="muted">${order.orderDate}</small></td><td>${escapeHtml(order.supplier)}</td><td>${order.items.map(item => `${escapeHtml(item.product)} × ${item.quantity}`).join('<br />')}</td><td>${money(order.total)}</td><td>${tag(order.status)}</td><td>${tag(order.financialStatus)}<br /><small class="muted">Pago: ${money(order.paid)}</small></td><td>${order.status !== 'recebido' && order.status !== 'cancelado' ? `<button class="text-link" data-action="receive-order" data-id="${order.id}">Receber</button>` : '<span class="muted">Concluído</span>'}</td></tr>`).join('') || '<tr><td colspan="7"><div class="empty-state">Nenhum pedido.</div></td></tr>'}</tbody></table></div></div>`; }
function renderFinance(type) { const entries = financialEntries(); const receivables = state.receivables || []; const expenses = financialExpenses(); const list = type === 'entries' ? entries : type === 'receivables' ? receivables : expenses; const title = type === 'entries' ? 'Entradas' : type === 'receivables' ? 'Contas a Receber' : 'Saídas'; const description = type === 'entries' ? 'Vendas recebidas e outros créditos consolidados.' : type === 'receivables' ? 'Títulos vinculados a vendas ou lançamentos manuais.' : 'Lançamentos manuais e custos operacionais.'; const valueOf = item => item.amount ?? item.value ?? 0; const rows = list.map(item => `<tr><td><strong>${escapeHtml(item.description || `Venda #${item.originId || item.id}`)}</strong><br /><small class="muted">${escapeHtml(item.category || item.origin || item.method || 'Financeiro')}</small></td><td>${money(valueOf(item))}</td><td>${item.dueDate || item.date || '—'}</td><td>${tag(item.status || (item.type === 'entrada' ? 'Recebido' : 'Pago'))}</td><td>${type === 'receivables' && item.status === 'ABERTA' ? `<button class="text-link" data-action="mark-receivable" data-id="${item.id}">Marcar paga</button>` : ''}</td></tr>`).join(''); return pageHeading('Financeiro', title, description, type === 'expenses' ? actionButton('Lançar saída', 'new-expense', '＋') : '') + `<div class="metric-grid"><div class="metric-box"><p>Total</p><strong>${money(list.reduce((sum, item) => sum + Number(valueOf(item)), 0))}</strong></div><div class="metric-box"><p>Registros</p><strong>${number(list.length)}</strong></div><div class="metric-box"><p>${type === 'receivables' ? 'Em aberto' : 'Status pendente'}</p><strong>${money(list.filter(item => /ABERTA|pendente/i.test(item.status || '')).reduce((sum, item) => sum + Number(valueOf(item)), 0))}</strong></div></div><div class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Descrição</th><th>Valor</th><th>Data / vencimento</th><th>Status</th><th></th></tr></thead><tbody>${rows || '<tr><td colspan="5"><div class="empty-state">Nenhum lançamento registrado.</div></td></tr>'}</tbody></table></div></div>`; }

function genericPage(id) { const map = { 'stock-variants': ['Estoque de roupas', 'Operacional', 'Área reservada para itens com variações de tamanho, cor ou lote.', '<div class="notice"><strong>Estrutura preservada:</strong> este módulo segue separado do estoque de produtos naturais, como no sistema de referência.</div>'], production: ['Produção', 'Operacional', 'Consuma insumos e adicione produtos próprios ao estoque.', '<div class="notice"><strong>Regra de produção:</strong> a próxima etapa vai permitir fichas de insumo com entrada do produto acabado e baixa dos componentes.</div>'], 'product-reports': ['Relatórios de produtos', 'Operacional', 'Giro, valor em estoque e necessidade de reposição.', `<div class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Produto</th><th>Categoria</th><th>Quantidade</th><th>Valor de custo</th><th>Status</th></tr></thead><tbody>${state.products.map(product => `<tr><td><strong>${escapeHtml(product.name)}</strong></td><td>${escapeHtml(product.category)}</td><td>${number(product.stock)}</td><td>${money(product.stock * product.cost)}</td><td>${product.stock <= product.min ? tag('Estoque baixo') : tag('Saudável')}</td></tr>`).join('')}</tbody></table></div></div>`], suppliers: ['Fornecedores', 'Operacional', 'Parceiros usados na compra e reposição do estoque.', `<div class="panel"><div class="panel-header"><div><h3 class="panel-title">Fornecedores cadastrados</h3><div class="panel-subtitle">Os produtos do pedido devem pertencer ao fornecedor selecionado.</div></div><button class="button button-primary button-small" data-action="new-supplier">＋ Novo fornecedor</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Fornecedor</th><th>Contato</th><th>Telefone</th></tr></thead><tbody>${state.suppliers.map(supplier => `<tr><td><strong>${escapeHtml(supplier.name)}</strong></td><td>${escapeHtml(supplier.contact)}</td><td>${escapeHtml(supplier.phone)}</td></tr>`).join('')}</tbody></table></div></div>`], clients: ['Clientes', 'Comercial', 'Cadastros que podem ser vinculados a vendas e contas a receber.', `<div class="panel"><div class="panel-header"><div><h3 class="panel-title">Clientes</h3><div class="panel-subtitle">${state.clients.length} cadastro(s) disponível(is) no caixa.</div></div><button class="button button-primary button-small" data-action="new-client">＋ Novo cliente</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Nome</th><th>Telefone</th><th>E-mail</th><th>Compras</th></tr></thead><tbody>${state.clients.map(client => `<tr><td><strong>${escapeHtml(client.name)}</strong></td><td>${escapeHtml(client.phone)}</td><td>${escapeHtml(client.email)}</td><td>${number(state.sales.filter(sale => sale.clientId === client.id).length)}</td></tr>`).join('')}</tbody></table></div></div>`], budgets: ['Orçamentos', 'Comercial', 'O orçamento deve poder ser convertido em venda sem perder o vínculo.', '<div class="notice"><strong>Vínculo planejado:</strong> o orçamento será convertido no caixa e a venda armazenará a origem do orçamento.</div>'], appointments: ['Agendamentos', 'Operacional', 'Agenda de retiradas, entregas e compromissos da loja.', '<div class="notice">Este módulo fica separado da venda de produtos, mas pode fornecer serviços vinculados ao caixa.</div>'], 'employee-costs': ['Custos por Funcionários', 'Financeiro', 'Custos de equipe que entram na visão financeira consolidada.', '<div class="notice">Cadastros e custos de funcionários serão conectados ao relatório financeiro nesta etapa.</div>'], 'financial-reports': ['Relatórios Financeiros', 'Financeiro', 'Resultado, CMV e consolidação das movimentações.', `<div class="metric-grid"><div class="metric-box"><p>Entradas consolidadas</p><strong>${money(total(financialEntries()))}</strong></div><div class="metric-box"><p>Saídas registradas</p><strong>${money(total(financialExpenses()))}</strong></div><div class="metric-box"><p>Saldo</p><strong>${money(total(financialEntries()) - total(financialExpenses()))}</strong></div></div>`], crm: ['CRM / RFM', 'Relacionamento', 'Frequência, recência e valor dos clientes.', '<div class="notice">O CRM será alimentado pelas vendas reais e não por dados separados do caixa.</div>'], users: ['Usuários', 'Administração', 'Usuários e perfis de acesso do sistema.', '<div class="panel"><div class="empty-state">Usuário atual: Admin · Administrador</div></div>'], access: ['Gestão de acessos', 'Administração', 'Permissões por módulo.', '<div class="notice">O acesso fixo de demonstração possui todas as permissões nesta primeira versão.</div>'], company: ['Minha Empresa', 'Administração', 'Dados da loja Saúde e Vida.', '<div class="panel"><div class="modal-form"><label>Nome da empresa<input value="Saúde e Vida" /></label><label>Segmento<input value="Produtos naturais e bem-estar" /></label></div></div>'], fiscal: ['Configuração Fiscal', 'Administração', 'Dados fiscais para uma etapa posterior de emissão.', '<div class="notice"><strong>Pendente:</strong> informe os dados fiscais antes de ativar emissão de documentos.</div>'] }; const item = map[id] || ['Módulo', 'Saúde e Vida', 'Em construção.', '<div class="panel"><div class="empty-state">Este módulo será detalhado nas próximas etapas.</div></div>']; return pageHeading(item[1], item[0], item[2]) + item[3]; }
function renderPage() { if (!state) return; document.getElementById('pageBreadcrumb').textContent = pageNames[currentPage] || 'Visão geral'; const content = currentPage === 'overview' ? renderOverview() : currentPage === 'stock' ? renderStock() : currentPage === 'cash' ? renderCash() : currentPage === 'orders' ? renderOrders() : ['entries', 'receivables', 'expenses'].includes(currentPage) ? renderFinance(currentPage) : genericPage(currentPage); document.getElementById('pageContent').innerHTML = content; renderSidebar(); }

function productOptions(includeEmpty = false) { return `${includeEmpty ? '<option value="">Não adicionar</option>' : ''}${state.products.map(product => `<option value="${product.id}">${escapeHtml(product.name)} · ${number(product.stock)} ${escapeHtml(product.unit || 'UN')}</option>`).join('')}`; }
function clientOptions() { return `<option value="">Consumidor final</option>${state.clients.map(client => `<option value="${client.id}">${escapeHtml(client.name)}</option>`).join('')}`; }
function supplierOptions() { return state.suppliers.map(supplier => `<option value="${supplier.id}">${escapeHtml(supplier.name)}</option>`).join(''); }
function openModal(kind, productId = '') { const product = state.products.find(item => item.id === Number(productId)); const forms = { 'new-product': ['Novo produto', 'Cadastre o produto com SKU, unidade, preço e estoque mínimo.', `<label>Nome<input name="name" required /></label><label>SKU / código<input name="code" placeholder="SV-000" /></label><label>Categoria<input name="category" required /></label><label>Unidade<select name="unit"><option>UN</option><option>KG</option><option>G</option><option>L</option><option>PCT</option></select></label><label>Estoque inicial<input name="stock" type="number" min="0" step="0.001" value="0" required /></label><label>Estoque mínimo<input name="min" type="number" min="0" step="0.001" value="0" required /></label><label>Preço de venda<input name="price" type="number" min="0" step="0.01" required /></label><label>Custo de compra<input name="cost" type="number" min="0" step="0.01" required /></label>`], 'new-entry': ['Registrar entrada', 'Entrada manual atualiza o saldo e cria um movimento rastreável.', `<label>Produto<select name="productId">${productOptions()}</select></label><label>Quantidade<input name="quantity" type="number" min="0.001" step="0.001" value="1" required /></label><label>Custo unitário<input name="cost" type="number" min="0" step="0.01" value="0" /></label><label class="full">Motivo<input name="reason" value="Compra sem pedido" /></label>`], 'new-sale': ['Nova venda', 'A venda valida o estoque, aceita pagamentos e registra os movimentos do caixa.', `<label>Produto<select name="productId">${productOptions()}</select></label><label>Quantidade<input name="quantity" type="number" min="0.001" step="0.001" value="1" required /></label><label>Cliente<select name="clientId">${clientOptions()}</select></label><label>Desconto<input name="discount" type="number" min="0" step="0.01" value="0" /></label><label>Taxa de entrega<input name="deliveryFee" type="number" min="0" step="0.01" value="0" /></label><label>Pagamento<select name="paymentType"><option value="PIX">PIX</option><option value="DINHEIRO">Dinheiro</option><option value="CARTAO">Cartão</option><option value="PRAZO">A prazo</option></select></label><label>Tipo de cartão<select name="cardType"><option value="debito">Débito</option><option value="credito">Crédito</option></select></label><label>Parcelas<input name="installments" type="number" min="1" value="1" /></label><label class="full">Observação<textarea name="observation"></textarea></label>`], 'new-order': ['Novo pedido de compra', 'O pedido pode ter dois itens nesta primeira versão; o recebimento atualiza o estoque.', `<label>Fornecedor<select name="supplierId">${supplierOptions()}</select></label><label>Data do pedido<input name="orderDate" type="date" value="${today()}" required /></label><label>Produto 1<select name="productId1">${productOptions()}</select></label><label>Quantidade 1<input name="quantity1" type="number" min="0.001" step="0.001" value="1" required /></label><label>Valor unitário 1<input name="unitPrice1" type="number" min="0" step="0.01" value="${product?.cost || state.products[0]?.cost || 0}" required /></label><label>Produto 2<select name="productId2">${productOptions(true)}</select></label><label>Quantidade 2<input name="quantity2" type="number" min="0.001" step="0.001" value="1" /></label><label>Valor unitário 2<input name="unitPrice2" type="number" min="0" step="0.01" value="0" /></label><label class="full">Observação<textarea name="notes"></textarea></label>`], 'open-shift': ['Abrir turno de caixa', 'Informe o valor inicial disponível no caixa.', `<label class="full">Valor de abertura<input name="openingAmount" type="number" min="0" step="0.01" value="0" required /></label>`], 'close-shift': ['Fechar turno de caixa', 'Informe o valor contado no fechamento.', `<label class="full">Valor de fechamento<input name="closingAmount" type="number" min="0" step="0.01" value="0" required /></label>`], 'new-client': ['Novo cliente', 'Cadastre os dados usados no caixa e nas contas a receber.', `<label>Nome completo<input name="name" required /></label><label>Telefone<input name="phone" /></label><label>E-mail<input name="email" type="email" /></label><label>CPF / CNPJ<input name="cpf" /></label><label class="full">Endereço<input name="address" /></label>`], 'new-supplier': ['Novo fornecedor', 'Fornecedor vinculado aos produtos e pedidos de compra.', `<label>Razão / nome<input name="name" required /></label><label>Telefone<input name="phone" /></label><label>E-mail<input name="contact" type="email" /></label><label class="full">CNPJ / CPF<input name="document" /></label>`], 'new-expense': ['Lançar saída', 'Saída financeira manual, separada das vendas e do recebimento de pedidos.', `<label>Descrição<input name="description" required /></label><label>Categoria<input name="category" value="Outros" required /></label><label>Valor<input name="amount" type="number" min="0.01" step="0.01" required /></label><label>Forma de pagamento<select name="method"><option>PIX</option><option>DINHEIRO</option><option>CARTAO</option></select></label>`] }; const form = forms[kind]; if (!form) return; document.getElementById('modalRoot').innerHTML = `<div class="modal-backdrop" data-action="close-modal"><div class="modal" onclick="event.stopPropagation()"><div class="modal-head"><div><h2>${form[0]}</h2><p>${form[1]}</p></div><button class="modal-close" data-action="close-modal">×</button></div><form id="activeModalForm" class="modal-form" data-kind="${kind}">${form[2]}<div class="modal-foot full"><button type="button" class="button button-secondary button-small" data-action="close-modal">Cancelar</button><button type="submit" class="button button-primary button-small">Salvar registro</button></div></form></div></div>`; show('modalRoot'); }

async function handleModal(kind, form) { const values = Object.fromEntries(new FormData(form).entries()); if (!serverAvailable) return showToast('Abra pelo servidor local para gravar operações com persistência.'); try { if (kind === 'new-product') await request('/api/products', { method: 'POST', body: JSON.stringify(values) }); if (kind === 'new-entry') await request('/api/stock/entry', { method: 'POST', body: JSON.stringify({ productId: values.productId, quantity: values.quantity, cost: values.cost, reason: values.reason }) }); if (kind === 'new-client') await request('/api/clients', { method: 'POST', body: JSON.stringify(values) }); if (kind === 'new-supplier') await request('/api/suppliers', { method: 'POST', body: JSON.stringify(values) }); if (kind === 'new-expense') await request('/api/finance/expenses', { method: 'POST', body: JSON.stringify(values) }); if (kind === 'new-sale') { const selected = state.products.find(product => product.id === Number(values.productId)); const gross = Number(selected.price) * Number(values.quantity); const totalSale = Math.max(0, gross - Number(values.discount || 0) + Number(values.deliveryFee || 0)); const paymentType = values.paymentType; await request('/api/sales', { method: 'POST', body: JSON.stringify({ clientId: values.clientId || null, items: [{ productId: Number(values.productId), quantity: Number(values.quantity), unitPrice: selected.price }], discount: Number(values.discount || 0), deliveryFee: Number(values.deliveryFee || 0), observation: values.observation, paymentType, onCredit: paymentType === 'PRAZO', payments: paymentType === 'PRAZO' ? [] : [{ method: paymentType, amount: totalSale, cardType: values.cardType, installments: Number(values.installments || 1) }] }) }); } if (kind === 'new-order') { const items = [{ productId: Number(values.productId1), quantity: Number(values.quantity1), unitPrice: Number(values.unitPrice1) }]; if (values.productId2) items.push({ productId: Number(values.productId2), quantity: Number(values.quantity2 || 1), unitPrice: Number(values.unitPrice2 || 0) }); await request('/api/orders', { method: 'POST', body: JSON.stringify({ supplierId: Number(values.supplierId), orderDate: values.orderDate, notes: values.notes, items }) }); } if (kind === 'open-shift') await request('/api/shifts/open', { method: 'POST', body: JSON.stringify({ openingAmount: values.openingAmount }) }); if (kind === 'close-shift') { const shift = currentShift(); if (!shift) throw new Error('Nenhum turno aberto'); await request(`/api/shifts/${shift.id}/close`, { method: 'POST', body: JSON.stringify({ closingAmount: values.closingAmount }) }); } closeModal(); await reloadState(); showToast('Operação registrada com sucesso.'); } catch (error) { showToast(error.message); } }

document.addEventListener('click', async event => { const button = event.target.closest('[data-action]'); const page = event.target.closest('[data-page]'); if (page && !button) { currentPage = page.dataset.page; searchTerm = ''; renderPage(); return; } if (!button) return; const action = button.dataset.action; if (action === 'show-login') { hide('landingView'); show('loginView'); } if (action === 'go-landing') { hide('loginView'); hide('appView'); show('landingView'); } if (action === 'go-dashboard') { currentPage = 'overview'; renderPage(); } if (action === 'logout') { hide('appView'); show('landingView'); } if (action === 'toggle-password') { const input = button.closest('.password-field').querySelector('input'); input.type = input.type === 'password' ? 'text' : 'password'; button.textContent = input.type === 'password' ? 'mostrar' : 'ocultar'; } if (action === 'close-modal') closeModal(); if (['new-product', 'new-entry', 'new-sale', 'new-order', 'new-client', 'new-supplier', 'new-expense', 'open-shift', 'close-shift'].includes(action)) openModal(action, button.dataset.id); if (action === 'stock-entry') openModal('new-entry', button.dataset.id); if (action === 'receive-order') { if (!serverAvailable) return showToast('Abra pelo servidor local para atualizar o estoque.'); try { await request(`/api/orders/${button.dataset.id}`, { method: 'PUT', body: JSON.stringify({ status: 'recebido' }) }); await reloadState(); showToast('Pedido recebido: estoque e movimento atualizados.'); } catch (error) { showToast(error.message); } } if (action === 'mark-receivable') { if (!serverAvailable) return showToast('Abra pelo servidor local para atualizar o financeiro.'); try { await request(`/api/finance/receivables/${button.dataset.id}`, { method: 'PATCH', body: JSON.stringify({ status: 'PAGA' }) }); await reloadState(); showToast('Conta marcada como paga.'); } catch (error) { showToast(error.message); } } if (action === 'show-notifications') showToast(`${state.products.filter(product => product.stock <= product.min && !product.infinite).length} alerta(s) de estoque.`); });
document.addEventListener('submit', async event => { if (event.target.id === 'loginForm') { event.preventDefault(); const values = Object.fromEntries(new FormData(event.target).entries()); if (values.email !== DEMO_USER.email || values.password !== DEMO_USER.password) return showToast('Acesso inválido. Use o login de demonstração.'); if (serverAvailable) { try { await request('/api/login', { method: 'POST', body: JSON.stringify({ email: values.email, password: values.password }) }); } catch (error) { return showToast(error.message); } } hide('loginView'); show('appView'); currentPage = 'overview'; renderPage(); showToast('Bem-vindo ao Saúde e Vida.'); } if (event.target.id === 'activeModalForm') { event.preventDefault(); await handleModal(event.target.dataset.kind, event.target); } });
document.addEventListener('input', event => { if (event.target.id === 'tableSearch') { searchTerm = event.target.value; renderPage(); const input = document.getElementById('tableSearch'); if (input) { input.focus(); input.setSelectionRange(searchTerm.length, searchTerm.length); } } });

async function boot() { state = await loadState(); renderSidebar(); }
function closeModal() { document.getElementById('modalRoot').innerHTML = ''; }
boot();
